//! Python `unidecode` 1.4.0 parity module.
//!
//! Ground truth: the live stack pins Python Unidecode 1.4.0 (see
//! `src/unidecode_tables.rs`, generated by a full codepoint sweep of the
//! Python distribution). The Rust crate `unidecode` 0.3 does NOT match it
//! (e.g. it drops U+30FC where Python maps it to `-`), so parity code must
//! not use the crate.
//!
//! Rules (identical to Python `unidecode.unidecode`):
//! - cp < 0x80        -> kept as-is
//! - cp > 0xEFFFF     -> dropped
//! - otherwise        -> table replacement for cp >= 0x80 (non-empty outputs
//!                        only; not found => dropped)

use crate::unidecode_tables;

/// Python-unidecode one `&str`.
pub fn unidecode(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for c in s.chars() {
        let cp = c as u32;
        if cp < 0x80 {
            out.push(c);
        } else if cp > 0xEFFFF {
            // dropped (Python: codepoint > 0xeffff -> skip)
        } else if let Some(rep) = unidecode_tables::lookup(cp) {
            out.push_str(rep);
        }
        // cp >= 0x80 not found in table => dropped
    }
    out
}

#[cfg(test)]
mod tests {
    use super::unidecode;

    #[test]
    fn parity_samples_python_140() {
        // Verified against Python unidecode 1.4.0 (rfvenv) 2026-11-23.
        // Verified against Python unidecode 1.4.0 (rfvenv) 2026-11-24:
        // 3 halfwidth kana ｶﾀﾅ -> "katana" (earlier expected value "katakana" was a vector typo).
        assert_eq!(unidecode("ｶﾀﾅ"), "katana");
        assert_eq!(unidecode("ｶﾀｶﾅ"), "katakana");
        assert_eq!(unidecode("ゾーン"), "zo-n");
        assert_eq!(unidecode("aーb"), "a-b"); // U+30FC -> '-'
        assert_eq!(unidecode("Æ"), "AE");
        assert_eq!(unidecode("ẞ"), "SS");
        assert_eq!(unidecode("ß"), "ss");
        // U+EFFFD (unassigned): Python unidecode 1.4.0 DROPS it -> "". An
        // earlier "D" vector came from the probe literal "\uEFFFD", which
        // Python parses as U+EFFF + 'D' (\u takes exactly 4 hex digits); the
        // dropped U+EFFF plus the kept 'D' yields "D". Re-verified 2026-11-24.
        assert_eq!(unidecode("\u{EFFFD}"), "");
        assert_eq!(unidecode("\u{EFFF}D"), "D");
        assert_eq!(unidecode("\u{0301}"), ""); // combining mark dropped
        assert_eq!(unidecode("e\u{0301}"), "e");
        assert_eq!(unidecode("\u{1F97A}"), ""); // < 0xEFFFF but unmapped
        assert_eq!(unidecode("\u{F0000}"), ""); // > 0xEFFFF dropped
        assert_eq!(unidecode("plain ascii"), "plain ascii");
    }
}
